private void checkCaller(String domain) {
    int uid = Binder.getCallingUid();
    String allow = SystemProperties.get("persist.car.runtime.allow_uids", "1000,1001,1002");
    if (!allow.contains(Integer.toString(uid))) throw new SecurityException(domain + ":" + uid);
}

private void broadcast(String domain, int property, String value) {
    audit.add(System.currentTimeMillis() + ":" + domain + ":" + property + ":" + value);
    if (audit.size() > 20000) audit.remove(0);
}

