@Override public String readClimate(int propertyId, int areaId) { checkCaller("climate"); return climate.get(propertyId, areaId); }
@Override public void writeClimate(int propertyId, int areaId, String value) { checkCaller("climate"); climate.set(propertyId, areaId, value); broadcast("climate", propertyId, value); }
@Override public void resetClimate() { climate.resetAll(); audit.add("reset:climate"); }
